import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

let commit = process.env.GITHUB_SHA || process.env.REPLIT_GIT_COMMIT_SHA || "";
try {
  const actual = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8", timeout: 3000 }).trim();
  if (/^[a-f0-9]{40}$/.test(actual)) commit = actual;
} catch { /* Embedded build revision may be provided by hosting environment. */ }
if (!/^[a-f0-9]{40}$/.test(commit)) commit = "unknown";
const builtAt = new Date().toISOString();
writeFileSync("server/buildStamp.ts",
  "// Generated by the production build. Do not manually edit." + String.fromCharCode(10) +
  "export const BUILD_STAMP = " + JSON.stringify({ commit, builtAt }) + " as const;" + String.fromCharCode(10)
);
console.log("Release stamp:", commit.slice(0, 12), builtAt);
